/* ============================================
   COMMAND PALETTE COMPONENT
   Modal Cmd+K launcher over a grouped command list
   ============================================ */

.ds-command-palette {
  position: fixed;
  inset: 0;
  z-index: 110; /* above Dialog and Drawer */
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: var(--padding-1000) var(--padding-400);
  opacity: 0;
  visibility: hidden; /* also removes the input from the tab order */
  pointer-events: none;
  /* Visibility waits out the fade only on close (duration token as delay);
     on open it must flip instantly — the open effect focuses the input a
     frame later, and focus() on a still-hidden element is a no-op, which
     left the palette opening without its caret. */
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard),
    visibility 0s linear var(--motion-duration-fast);
}

.ds-command-palette--open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard),
    visibility 0s;
}

/* ============================================
   BACKDROP
   ============================================ */

.ds-command-palette__backdrop {
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
}

/* ============================================
   PANEL
   ============================================ */

.ds-command-palette__panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 560px;
  max-height: 60vh;
  margin-top: 10vh;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600); /* 24px — the floating-surface shell */
  background-color: var(--color-bg-glass);
  box-shadow: var(--shadow-floating);
  /* The glass token is deliberately translucent; this blur is what keeps
     the page readable through the panel. */
  backdrop-filter: blur(24px);
  overflow: hidden;
  transform: scale(0.98);
  transition: transform var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-command-palette--open .ds-command-palette__panel {
  transform: scale(1);
}

/* ============================================
   SEARCH ROW
   ============================================ */

.ds-command-palette__search {
  display: flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */
  padding: var(--padding-400) var(--padding-500); /* 16px 20px */
  border-bottom: var(--border-025) solid var(--color-divider);
  flex-shrink: 0;
  transition: border-color var(--motion-duration-fast) var(--motion-ease-standard);
}

/* The focused field marks the whole row with the active input border, the
   same signal a focused Input gives its own edge. */
.ds-command-palette__search:focus-within {
  border-bottom-color: var(--color-input-border-selected);
}

.ds-command-palette__search-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

.ds-command-palette__input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background-color: transparent;
  padding: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-input-text-primary);
}

.ds-command-palette__input::placeholder {
  color: var(--color-input-text-placeholder);
}

.ds-command-palette__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background-color: transparent;
  color: var(--color-icon-primary);
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-command-palette__close:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-command-palette__close:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-command-palette__close .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   LIST
   ============================================ */

.ds-command-palette__list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: var(--padding-200);
  /* Quiet scrollbar, ChatThread's recipe: thin and token-coloured instead
     of the 15px native chrome rail a classic-scrollbar platform would draw
     inside the panel. The stable gutter matters here because filtering
     toggles overflow — without it every keystroke that crosses the
     threshold reflows the rows sideways. */
  scrollbar-width: thin;
  scrollbar-gutter: stable;
  scrollbar-color: var(--color-divider) transparent;
  /* The scroll lock lets wheel and touch through only inside this list, so
     hitting its ends must not chain the leftover delta to the page. */
  overscroll-behavior: contain;
}

.ds-command-palette__status {
  padding: var(--padding-500);
  text-align: center;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  margin: 0;
}

/* ============================================
   GROUP
   ============================================ */

.ds-command-palette__group + .ds-command-palette__group {
  margin-top: var(--gap-100); /* 4px */
}

.ds-command-palette__group-label {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  padding: var(--padding-150) var(--padding-300);
  margin: 0;
  user-select: none;
}

/* ============================================
   COMMAND ROW
   ============================================ */

.ds-command-palette__command {
  display: flex;
  align-items: center;
  gap: var(--gap-300);
  padding: var(--padding-300); /* 12px — 8px list inset keeps the text edge on the search row's 20px */
  border-radius: var(--radius-200);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-command-palette__command--active {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-command-palette__command--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-command-palette__command-icon {
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

.ds-command-palette__command-text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  flex: 1;
  min-width: 0;
}

.ds-command-palette__command-label {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-command-palette__command-description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ============================================
   SHORTCUT KEYS
   ============================================ */

.ds-command-palette__shortcut {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  flex-shrink: 0;
}

/* Keycaps render through the Kbd component (compact size) */

/* The trailing slot: an arbitrary badge or affordance at the row's right
   edge, after any keycaps. The row's gap spaces it; it never shrinks, so
   the label and description ellipsize first. */
.ds-command-palette__trailing {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

/* ============================================
   FOOTER HINTS
   ============================================ */

.ds-command-palette__footer {
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  padding: var(--padding-300) var(--padding-500);
  border-top: var(--border-025) solid var(--color-divider);
  flex-shrink: 0;
  flex-wrap: wrap;
}

.ds-command-palette__hint {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 480px) {
  .ds-command-palette__panel {
    margin-top: var(--gap-400);
    max-height: 75vh;
  }

  .ds-command-palette__footer {
    display: none;
  }
}

/* ============================================
   REDUCED MOTION
   ============================================ */

@media (prefers-reduced-motion: reduce) {
  .ds-command-palette,
  .ds-command-palette__panel {
    transition: none;
  }
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-command-palette .material-symbols-rounded {
  color: inherit;
}

'use client';

import React, { useState, useRef, useEffect, useMemo, useCallback, useId } from 'react';
import ReactDOM from 'react-dom';
import { Kbd } from '../Kbd/Kbd';
import './CommandPalette.css';
import '../../fonts/material-symbols.css';
import { useMounted } from '../../behaviors/useMounted';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';

export interface CommandPaletteCommand {
  /** Stable identifier */
  id: string;
  /** Display label — the primary text matched when filtering */
  label: string;
  /** Optional secondary line under the label */
  description?: string;
  /** Optional icon — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Keyboard shortcut shown on the right, e.g. ['⌘', 'P'] */
  shortcut?: string[];
  /** Custom node at the row's right edge, after any `shortcut` — a badge or affordance the keycap slot can't express. It renders inside the option row, so keep it non-interactive: a focusable element here would nest controls. */
  trailing?: React.ReactNode;
  /** Extra terms that should match this command when filtering */
  keywords?: string[];
  /** Whether the command is disabled */
  disabled?: boolean;
  /** Called when this command is chosen */
  onSelect?: () => void;
}

export interface CommandPaletteGroup {
  /** Group heading */
  label: string;
  /** Commands within the group */
  commands: CommandPaletteCommand[];
}

export interface CommandPaletteProps {
  /** Whether the palette is open */
  open: boolean;
  /** Callback when the palette requests to open or close */
  onOpenChange: (open: boolean) => void;
  /** Commands, grouped under headings */
  groups: CommandPaletteGroup[];
  /** Placeholder for the search field */
  placeholder?: string;
  /** Message shown when the query matches nothing */
  emptyMessage?: string;
  /** Show a loading affordance in place of results */
  loading?: boolean;
  /**
   * Bind Cmd+K / Ctrl+K globally to toggle the palette. Set to false when the
   * host app owns the shortcut.
   */
  hotkey?: boolean;
  /** Called with the chosen command, after its own `onSelect` */
  onSelect?: (command: CommandPaletteCommand) => void;
  /** Called as the user types, for async/server-side search */
  onSearchChange?: (query: string) => void;
  /** Skip built-in filtering — use when commands are filtered upstream */
  manualFiltering?: boolean;
  /** Hide the hint row at the bottom of the panel */
  hideFooter?: boolean;
  /** Additional CSS classes */
  className?: string;
}

/**
 * CommandPalette component — a modal Cmd+K launcher that searches a grouped
 * command list. Filtering matches labels, descriptions, and keywords; the
 * arrow keys move a highlight that stays in view, and Enter runs the command.
 */
export const CommandPalette = ({
  open,
  onOpenChange,
  groups,
  placeholder = 'Type a command or search…',
  emptyMessage = 'No matching commands',
  loading = false,
  hotkey = true,
  onSelect,
  onSearchChange,
  manualFiltering = false,
  hideFooter = false,
  className = '',
}: CommandPaletteProps) => {
  const [query, setQuery] = useState('');
  const [rawActiveIndex, setActiveIndex] = useState(0);
  const [prevOpen, setPrevOpen] = useState(open);
  const inputRef = useRef<HTMLInputElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const generatedId = useId();
  const baseClass = 'ds-command-palette';

  // SSR guard — only render the portal on the client
  const mounted = useMounted();

  const matches = useCallback(
    (command: CommandPaletteCommand) => {
      const q = query.trim().toLowerCase();
      if (manualFiltering || q === '') return true;
      const haystack = [command.label, command.description ?? '', ...(command.keywords ?? [])]
        .join(' ')
        .toLowerCase();
      return haystack.includes(q);
    },
    [manualFiltering, query]
  );

  const filteredGroups = useMemo(
    () =>
      groups
        .map((group) => ({ ...group, commands: group.commands.filter(matches) }))
        .filter((group) => group.commands.length > 0),
    [groups, matches]
  );

  // Flat, in-render-order list of the selectable (non-disabled) commands
  const flatCommands = useMemo(
    () => filteredGroups.flatMap((g) => g.commands).filter((c) => !c.disabled),
    [filteredGroups]
  );

  // Clear the query once the palette closes. Adjusting state during render is
  // React's supported pattern for reacting to a prop change — doing it in an
  // effect would queue an extra render pass.
  if (prevOpen !== open) {
    setPrevOpen(open);
    if (!open) {
      setQuery('');
      setActiveIndex(0);
    }
  }

  // Clamp rather than reset, so a shrinking result set (async results landing,
  // a group filtered out) can never leave the highlight past the end.
  const activeIndex = Math.min(rawActiveIndex, Math.max(0, flatCommands.length - 1));

  // Global Cmd+K / Ctrl+K toggle
  useEffect(() => {
    if (!hotkey) return;

    const handleHotkey = (e: KeyboardEvent) => {
      if (e.key.toLowerCase() === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        onOpenChange(!open);
      }
    };

    document.addEventListener('keydown', handleHotkey);
    return () => document.removeEventListener('keydown', handleHotkey);
  }, [hotkey, open, onOpenChange]);

  // Shared overlay behaviors (src/behaviors/) — see Dialog for the contract.
  // Initial focus goes straight to the search field. The scroll lock uses the
  // cancel-events strategy: hiding body overflow removes the document
  // scrollbar, and the rail blinking out reads as a jump on classic-scrollbar
  // platforms — so the page keeps its scrollbar and scroll *input* is
  // cancelled outside the command list instead. Dragging the scrollbar thumb
  // itself remains possible; the scrim makes that a deliberate act.
  useLayer({ open, onDismiss: () => onOpenChange(false) });
  useFocusScope(panelRef, { active: open, initialFocus: () => inputRef.current });
  useScrollLock(open, { strategy: 'cancel-events', allowWithin: listRef });

  const runCommand = (command: CommandPaletteCommand) => {
    if (command.disabled) return;
    command.onSelect?.();
    onSelect?.(command);
    onOpenChange(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex((prev) =>
          flatCommands.length === 0 ? 0 : (prev + 1) % flatCommands.length
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex((prev) =>
          flatCommands.length === 0 ? 0 : (prev - 1 + flatCommands.length) % flatCommands.length
        );
        break;
      case 'Home':
        e.preventDefault();
        setActiveIndex(0);
        break;
      case 'End':
        e.preventDefault();
        setActiveIndex(Math.max(0, flatCommands.length - 1));
        break;
      case 'Enter':
        e.preventDefault();
        if (flatCommands[activeIndex]) runCommand(flatCommands[activeIndex]);
        break;
    }
  };

  // Keep the highlighted row in view
  useEffect(() => {
    if (!open || !listRef.current) return;
    const active = listRef.current.querySelector<HTMLElement>(
      `[data-command-index="${activeIndex}"]`
    );
    active?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex, open]);

  const handleQueryChange = (next: string) => {
    setQuery(next);
    // A new query re-ranks the list, so highlight the top result again
    setActiveIndex(0);
    onSearchChange?.(next);
  };

  const listboxId = `${generatedId}-listbox`;
  const activeCommand = flatCommands[activeIndex];
  const activeDescendantId = activeCommand
    ? `${generatedId}-command-${activeCommand.id}`
    : undefined;

  const classes = [baseClass, open ? `${baseClass}--open` : '', className]
    .filter(Boolean)
    .join(' ');

  // Running index across groups so keyboard order matches visual order
  let commandIndex = 0;

  const palette = (
    <div className={classes}>
      <div className={`${baseClass}__backdrop`} onClick={() => onOpenChange(false)} />

      <div
        className={`${baseClass}__panel`}
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-label="Command palette"
      >
        <div className={`${baseClass}__search`}>
          <span className={`${baseClass}__search-icon material-symbols-rounded`} aria-hidden="true">
            search
          </span>
          <input
            ref={inputRef}
            type="text"
            className={`${baseClass}__input`}
            role="combobox"
            autoComplete="off"
            aria-expanded
            aria-controls={listboxId}
            aria-autocomplete="list"
            aria-activedescendant={activeDescendantId}
            aria-label={placeholder}
            placeholder={placeholder}
            value={query}
            onChange={(e) => handleQueryChange(e.target.value)}
            onKeyDown={handleKeyDown}
          />
          <button
            type="button"
            className={`${baseClass}__close`}
            onClick={() => onOpenChange(false)}
            aria-label="Close command palette"
          >
            <span className="material-symbols-rounded" aria-hidden="true">
              close
            </span>
          </button>
        </div>

        <div className={`${baseClass}__list`} role="listbox" id={listboxId} ref={listRef}>
          {loading && <p className={`${baseClass}__status`}>Loading…</p>}

          {!loading && filteredGroups.length === 0 && (
            <p className={`${baseClass}__status`} aria-live="polite">
              {emptyMessage}
            </p>
          )}

          {!loading &&
            filteredGroups.map((group) => (
              <div
                key={group.label}
                className={`${baseClass}__group`}
                role="group"
                aria-label={group.label}
              >
                <p className={`${baseClass}__group-label`}>{group.label}</p>

                {group.commands.map((command) => {
                  // Disabled commands stay visible but are skipped by the highlight
                  const index = command.disabled ? -1 : commandIndex++;
                  const isActive = index === activeIndex;

                  return (
                    <div
                      key={command.id}
                      id={`${generatedId}-command-${command.id}`}
                      data-command-index={index}
                      className={[
                        `${baseClass}__command`,
                        isActive ? `${baseClass}__command--active` : '',
                        command.disabled ? `${baseClass}__command--disabled` : '',
                      ]
                        .filter(Boolean)
                        .join(' ')}
                      role="option"
                      aria-selected={isActive}
                      aria-disabled={command.disabled}
                      onMouseEnter={() => index >= 0 && setActiveIndex(index)}
                      onMouseDown={(e) => e.preventDefault()}
                      onClick={() => runCommand(command)}
                    >
                      {command.icon && (
                        <span
                          className={`${baseClass}__command-icon${typeof command.icon === 'string' ? ' material-symbols-rounded' : ''}`}
                          aria-hidden="true"
                        >
                          {command.icon}
                        </span>
                      )}

                      <span className={`${baseClass}__command-text`}>
                        <span className={`${baseClass}__command-label`}>{command.label}</span>
                        {command.description && (
                          <span className={`${baseClass}__command-description`}>
                            {command.description}
                          </span>
                        )}
                      </span>

                      {command.shortcut && command.shortcut.length > 0 && (
                        <span className={`${baseClass}__shortcut`}>
                          {command.shortcut.map((key, i) => (
                            <Kbd key={i} size="compact">
                              {key}
                            </Kbd>
                          ))}
                        </span>
                      )}

                      {command.trailing && (
                        <span className={`${baseClass}__trailing`}>{command.trailing}</span>
                      )}
                    </div>
                  );
                })}
              </div>
            ))}
        </div>

        {!hideFooter && (
          <div className={`${baseClass}__footer`}>
            <span className={`${baseClass}__hint`}>
              <Kbd size="compact">↑</Kbd>
              <Kbd size="compact">↓</Kbd>
              to navigate
            </span>
            <span className={`${baseClass}__hint`}>
              <Kbd size="compact">↵</Kbd>
              to select
            </span>
            <span className={`${baseClass}__hint`}>
              <Kbd size="compact">esc</Kbd>
              to close
            </span>
          </div>
        )}
      </div>
    </div>
  );

  if (!mounted) return null;
  return ReactDOM.createPortal(palette, document.body);
};
